const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const fujiPoint = ee.Geometry.Point([138.727778, 35.360556]);
    const fujiArea = fujiPoint.buffer(10000); // 10 km buffer

    const targetYear = 2020;
    const historicalStartYear = 2005;
    const historicalEndYear = 2015;
    const month = 12;

    const collectionId = 'MODIS/061/MOD10A1';
    const bandName = 'NDSI_Snow_Cover';

    // 2. Data Acquisition & Processing Function
    const getDecemberMeanNDSI = function(year) {
        const startDate = ee.Date.fromYMD(year, month, 1);
        const endDate = startDate.advance(1, 'month');

        let collection = ee.ImageCollection(collectionId)
            .filterBounds(fujiArea)
            .filterDate(startDate, endDate)
            .select(bandName);

        // Check for empty collection
        const size = collection.size().getInfo();
        if (size === 0) {
            return ee.Dictionary({ 'mean': null, 'count': 0, 'size': 0, 'year': year });
        }

        // Mask out non-snow/invalid pixels based on product documentation
        // Values > 100 are fill, missing data, cloud, etc.
        const maskedCollection = collection.map(function(image) {
            return image.updateMask(image.select(bandName).lte(100));
        });

        const meanImage = maskedCollection.mean();

        const stats = meanImage.reduceRegion({
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: fujiArea,
            scale: 500, // Native scale of the product
            maxPixels: 1e9
        });

        return stats.set('size', size).set('year', year);
    };

    // 3. Calculation for Target Year (2020)
    const targetStats = getDecemberMeanNDSI(targetYear);
    const targetMeanNDSI = ee.Number(targetStats.get('NDSI_Snow_Cover')).getInfo();
    const targetPixelCount = ee.Number(targetStats.get('count')).getInfo();
    const targetImageCount = ee.Number(targetStats.get('size')).getInfo();

    console.log(`Dec 2020: Mean NDSI = ${targetMeanNDSI ? targetMeanNDSI.toFixed(2) : 'N/A'}, Images = ${targetImageCount}, Valid Pixels = ${targetPixelCount}`);

    // Validation checks for target year
    if (targetImageCount === 0) {
        console.log("Evidence: No images found for December 2020.");
        console.log("A"); // The condition "lower than any other" is vacuously true if comparison set is empty or has no valid pixels.
        return;
    }
    if (targetPixelCount === 0) {
        console.log("Evidence: 0 valid pixels found for December 2020 after masking.");
        console.log("A"); // Vacuously true, as null is not greater than any valid historical value.
        return;
    }
    if (targetMeanNDSI === null) {
        console.log("Evidence: Calculation failed for December 2020.");
        console.log("C3");
        return;
    }

    // 4. Calculation for Historical Years
    const historicalYears = ee.List.sequence(historicalStartYear, historicalEndYear);
    const historicalStatsList = historicalYears.map(getDecemberMeanNDSI);
    const historicalResults = historicalStatsList.getInfo();

    let lowestHistoricalMean = Infinity;
    let validHistoricalYearsCount = 0;

    historicalResults.forEach(result => {
        const mean = result.NDSI_Snow_Cover;
        const count = result.count;
        console.log(`Dec ${result.year}: Mean NDSI = ${mean ? mean.toFixed(2) : 'N/A'}, Images = ${result.size}, Valid Pixels = ${count}`);
        if (mean !== null && count > 0) {
            validHistoricalYearsCount++;
            if (mean < lowestHistoricalMean) {
                lowestHistoricalMean = mean;
            }
        }
    });

    // 5. Validation & Final Answer
    if (validHistoricalYearsCount === 0) {
        console.log("Evidence: No valid data found for any historical year (2005-2015).");
        // If there's nothing to compare against, the condition is vacuously true.
        console.log("A");
        return;
    }

    console.log(`Target Mean NDSI (2020): ${targetMeanNDSI.toFixed(2)}`);
    console.log(`Lowest Historical Mean NDSI (2005-2015): ${lowestHistoricalMean.toFixed(2)}`);

    if (targetMeanNDSI < lowestHistoricalMean) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D");
});
